package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Step of {@code POST /api/owners} that assigns the owner's {@code membershipNumber}, formatted
 * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
 * {@code registrationDate} year, zero-padded (e.g. {@code 'SYD-SMI-0007-M26'}).
 *
 * <p>Runs after {@link AssignCustomerCode} has set the {@code customerCode} and after
 * {@link BuildOwner} has set the {@code registrationDate}, and before {@link SaveOwner}. Derived
 * entirely from the owner's own fields, so it is seed-independent. {@code @Val} yields the built
 * owner so the number is mutated in place and persisted by the save step.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        int yy = Math.floorMod(owner.getRegistrationDate().getYear(), 100);
        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
    }
}

package org.springframework.samples.petclinic.rest.function.common;

/**
 * Derives a single Luhn check digit over the digits contained in a value.
 *
 * <p>Used for the owner's {@code checkDigit}, computed over the digits of its
 * {@code customerCode}. Non-digit characters are ignored, so the separators in a code such as
 * {@code 'SYD-SMI-0007'} do not contribute; the rightmost digit is doubled first per the
 * standard Luhn algorithm.
 */
public final class CheckDigits {

    private CheckDigits() {
    }

    /** The Luhn check digit (0-9) over the digits contained in {@code value}; 0 when null. */
    public static int luhnOf(String value) {
        if (value == null) {
            return 0;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that runs after {@link ValidateOwnerFields} has published the
 * request. Rejects the request when the named city already contains {@value #MAX_OWNERS_PER_CITY}
 * or more owners, so a full city is a 409 Conflict rather than an over-capacity create. City
 * matching is case-insensitive, consistent with {@link AssignCustomerCode}.
 */
public class RejectCityAtCapacity {

    /** Maximum number of owners a single city may contain. */
    static final int MAX_OWNERS_PER_CITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
                .map(Owner::getCity)
                .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
                .count();
        if (count >= MAX_OWNERS_PER_CITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
